window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-18191\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζειρά, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 24 na letra ζ · nº geral 18191</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">manto até os pés dos árabes, dos trácios.</p></section></article>\n<article id=\"entry-dgp-18192\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζέσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 25 na letra ζ · nº geral 18192</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ebulição; fervura. 〈ζέω〉</p></section></article>\n<article id=\"entry-dgp-18193\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζέσσε(ν)</h1><div class=\"entry-meta\"><span>DGP · ordem 26 na letra ζ · nº geral 18193</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. aor. poét. de ζέω.</p></section></article>\n<article id=\"entry-dgp-18194\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζεστός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 27 na letra ζ · nº geral 18194</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. 1 fervido 2 que fervilha; férvido; fervente 3 quente; ardente. 〈ζέω〉</p></section></article>\n<article id=\"entry-dgp-18195\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζευγηλατέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 28 na letra ζ · nº geral 18195</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">conduzir uma parelha de bois ou cavalos. 〈ζεῦγος, ἐλαύνω〉</p></section></article>\n<article id=\"entry-dgp-18196\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζευγηλάτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 29 na letra ζ · nº geral 18196</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">condutor de uma parelha de bois ou cavalos. 〈ζεῦγος, ἐλαύνω〉</p></section></article>\n<article id=\"entry-dgp-18197\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζευγίτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 30 na letra ζ · nº geral 18197</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 jungido aos pares; atrelado; colocado sob jugo (animal) 2 enfileirado (soldados) 3 justaposto: κάλαμος ζ. flauta dupla em que o sopro passa por dois caniços justapostos ♦ οἱ ζευγῖται 4 zeugitas, 3a classe de cidadãos, em Atenas. 〈ζεῦγος〉</p></section></article>\n<article id=\"entry-dgp-18198\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζεύγλη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 31 na letra ζ · nº geral 18198</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 canga; jugo 2 correia para controlar o timão da charrua. 〈ζεύγνυμι〉</p></section></article>\n<article id=\"entry-dgp-18199\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζεῦγμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 32 na letra ζ · nº geral 18199</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 canga; jugo 2 laço; liame 3 ligação 4 ponte de barcas 5 barragem; quebra-mar. 〈ζεύγνυμι〉</p></section></article>\n<article id=\"entry-dgp-18200\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζευγνύμεν, ζευγνύμεναι</h1><div class=\"entry-meta\"><span>DGP · ordem 33 na letra ζ · nº geral 18200</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. pres. ép. de ζεύγνυμι.</p></section></article>\n<article id=\"entry-dgp-18201\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζεύγνυμι</h1><div class=\"entry-meta\"><span>DGP · ordem 34 na letra ζ · nº geral 18201</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ζεύξω, aor. ἔζευξα, perf. desus.; pas. aor. ἐζεύχθην, aor.2 ἐζύγην, perf. ἔζευγμαι) ativa 1 colocar sob o jugo; atrelar (animais) 2 tomar como cônjuge; desposar (mulher), ac. 3 dar uma filha, ac., em casamento a, dat. 4 unir com uma ponte as duas margens de, ac. 5 juntar; ligar; ajustar média 6 colocar sob o jugo para uso próprio (animais) 7 desposar (mulher) 8 unir com uma ponte as duas margens de um rio 9 ligar a si passiva 10 submeter-se ao jugo de; estar sujeito a; sujeitar-se à lei de, dat. 1 ὑπ᾽ ἀμάξῃσιν βόας ἡμιόνους τε ζεύγνυσαν hom. atrelaram aos carros bois e mulas 2 τίς ταύτην ἔζευξε; eur. quem a desposou? 3 ζευγνύναι τὴν θυγατέρα τινί ap. dar a filha em casamento a alguém 4 μηχαναῖς ἔζευξεν Ἕλλης πόντον ésql. com engenhosidade ligou as duas margens do Helesponto, ποταμὸν ζεῦξαι her. lançar uma ponte 5 ζεύξαντες τὰς παλαιὰς (ναῦς) ὥστε πλωΐμους εἶναι tuc. tendo ajustado as pranchas dos antigos navios de modo que pudessem navegar, ἀσκοὺς δεσμοῖς ζευγνύναι xen. ligar os odres com as cordas 6 ἵππους ζεύγνυντο hom. atrelavam os cavalos, ζεύξομαι ἄρα πώλους eur. pois bem! atrelarei os cavalos 7 ἄκοιτιν ζεύξαθαι eur. tomar uma esposa 8 ζεύγνυσθαι τὸν Βόσπορον her. lançar uma ponte sobre o Bósforo 9 τόνδ᾽ ἐν ὅρκοις ζεύξομαι eur. eu o manterei preso aos juramentos (feitos por mim) 10 πότμῳ ζυγείς pínd. submissão ao destino, ἀνάγκῃ ζυγείς sóf. sujeito à necessidade, ὁρκίοισιν ζυγείς eur. unido por juramentos.</p></section></article>\n<article id=\"entry-dgp-18202\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζεύγνυντο</h1><div class=\"entry-meta\"><span>DGP · ordem 35 na letra ζ · nº geral 18202</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. impf. pas. aor. méd. poét. de ζεύγνυμι.</p></section></article>\n<article id=\"entry-dgp-18203\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζεύγνυσαν</h1><div class=\"entry-meta\"><span>DGP · ordem 36 na letra ζ · nº geral 18203</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. impf. ép., ζεύγνυσθαι inf. pres. pas., ζευγνύσθην 3ª dual impf. poét., de ζεύγνυμι.</p></section></article>\n<article id=\"entry-dgp-18204\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζευγνύω</h1><div class=\"entry-meta\"><span>DGP · ordem 37 na letra ζ · nº geral 18204</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf.) = ζεύγνυμι.</p></section></article>\n<article id=\"entry-dgp-18205\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζεῦγος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 38 na letra ζ · nº geral 18205</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 junta (de dois animais de tração) 2 carro puxado por uma junta: ζεύγεϊ, ἐπὶ ζεύγους sobre um carro 3 casal (de amantes, de esposos) 4 parelha (de animais) 5 par (de coisas), dupla (de pessoas): κατὰ ζεῦγος, κατὰ ζεύγη, ἐς ζεύγεα em dupla, aos pares 6 grupo; conjunto de mais de dois: ζ. τέθριππον ésql. quadriga. 〈ζεύγνυμι〉</p></section></article>\n<article id=\"entry-dgp-18206\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζευγοτρόφος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 39 na letra ζ · nº geral 18206</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que mantém uma junta. 〈ζεῦγος, τρέφω〉</p></section></article>\n<article id=\"entry-dgp-18207\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζευκτήριος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 40 na letra ζ · nº geral 18207</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que serve para ligar, juntar, unir a, gen. ♦ ἡ ζευκτηρία 2 bíbl. corda; amarra do leme ♦ τὸ ζευκτήριον 3 jugo. 〈ζεύγνυμι〉</p></section></article>\n<article id=\"entry-dgp-18208\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζευκτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 41 na letra ζ · nº geral 18208</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 colocado sob jugo; atrelado 2 ligado; unido. 〈ζεύγνυμι〉</p></section></article>\n<article id=\"entry-dgp-18209\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζεύξατε</h1><div class=\"entry-meta\"><span>DGP · ordem 42 na letra ζ · nº geral 18209</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª pl. imper. aor., ζεῦξαν 3ª pl. ind. aor. poét., ζεύξειεν 3a pl. opt. aor. poét., ζεῦξε(ν) 3ª sing. ind. aor. poét., de ζεύγνυμι.</p></section></article>\n<article id=\"entry-dgp-18210\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζεῦξις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 43 na letra ζ · nº geral 18210</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de colocar sob o jugo; atrelagem 2 ligação por meio de uma ponte. 〈ζεύγνυμι〉</p></section></article>\n<article id=\"entry-dgp-18211\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ζεῦξις, ιδος,</h1><div class=\"entry-meta\"><span>DGP · ordem 44 na letra ζ · nº geral 18211</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ac. -ιν (ὁ) Zêuxis, pintor.</p></section></article>\n<article id=\"entry-dgp-18212\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ζεύς,</h1><div class=\"entry-meta\"><span>DGP · ordem 45 na letra ζ · nº geral 18212</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">voc. Ζεῦ, gen. Διός e Ζηνός, dat. Διί e Ζηνί, ac. Δία e Ζῆνα (ὁ) Zeus, filho de Cronos e de Réia, esposo de Hera, deus do céu, deus supremo, pai dos deuses e dos homens.</p></section></article>\n<article id=\"entry-dgp-18213\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζεφυρίη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 46 na letra ζ · nº geral 18213</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. o sopro de zéfiro. 〈ζεφύριος〉</p></section></article>\n<article id=\"entry-dgp-18214\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζεφύριος, ος</h1><div class=\"entry-meta\"><span>DGP · ordem 47 na letra ζ · nº geral 18214</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e α, ον 1 de zéfiro; do vento oeste 2 do oeste: Ζεφύριοι Λοκροί pínd. os Lócrios do oeste ♦ οἱ ζεφύριοι 3 os ventos do oeste ♦ τὸ Ζεφύριον 4 Zefirião, n. de promontório na Magna Grécia e em Chipre. 〈ζέφυρος〉</p></section></article>\n<article id=\"entry-dgp-18215\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζέφυρος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 48 na letra ζ · nº geral 18215</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 zéfiro, vento do oeste 2 vento violento; borrasca 3 brisa; aragem 4 Zéfiro, person.</p></section></article>\n<article id=\"entry-dgp-18216\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζέω</h1><div class=\"entry-meta\"><span>DGP · ordem 49 na letra ζ · nº geral 18216</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἔζεον, fut. ζέσω, aor. ἔζεσα, perf. desus.; pas. aor. ἐζέσθην) 1 (líquido) levantar fervura; ferver 2 (sólido) queimar como água fervente; escaldar 3 (líquido) fermentar 4 (mar) borbulhar; agitar-se 5 arder moralmente 6 fervilhar; formigar de, gen. ou dat.: ζ. σκωλήκων luc. fervilhar de vermes, ζ. φθειρσί luc. fervilhar de pulgas 7 causat. fazer ferver.</p></section></article>\n<article id=\"entry-dgp-18217\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζῆ, ζῇ</h1><div class=\"entry-meta\"><span>DGP · ordem 50 na letra ζ · nº geral 18217</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ζάω.</p></section></article>\n<article id=\"entry-dgp-18218\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζηλεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 51 na letra ζ · nº geral 18218</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. = ζηλόω.</p></section></article>\n<article id=\"entry-dgp-18219\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζηλήμων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 52 na letra ζ · nº geral 18219</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος 1 ciumento, gen. 2 invejoso. 〈ζῆλος〉</p></section></article>\n<article id=\"entry-dgp-18220\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζῆλος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 53 na letra ζ · nº geral 18220</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ardor; ciúme; zelo por algo ou alguém, gen. ou πρός e ac. 2 emulação; rivalidade em algo, gen., com alguém, πρός e ac. 3 ódio; ciúme 4 objeto de inveja ou de ciúme 5 tard. exuberância de estilo 6 bíbl. ardor do fogo ♦ ὁ Ζῆλος 7 Zelo, person. 〈ζέω〉</p></section></article>\n<article id=\"entry-dgp-18221\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζηλοτυπέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 54 na letra ζ · nº geral 18221</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ter ciúme de, ac.: ζ. δούλην ἐπὶ ἀνδρί plut. sentir ciúme de uma escrava por causa do marido, i.e., dos sentimentos do marido por uma escrava 2 ter inveja de, ac. 3 rivalizar com, dat. 4 simular; imitar: κάθαρμα ζηλοτυποῦν ἀρετήν ésqn. escória que simula virtude. 〈ζηλότυπος〉</p></section></article>\n<article id=\"entry-dgp-18222\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζηλοτυπία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 55 na letra ζ · nº geral 18222</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 rivalidade 2 inveja 3 ciúme nocivo de alguém, πρός e ac., por causa de alguém ou algo, διά e ac. ou ὑπέρ e gen. 〈ζηλότυπος〉</p></section></article>\n<article id=\"entry-dgp-18223\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζηλότυπος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 56 na letra ζ · nº geral 18223</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ciumento 2 invejoso. 〈ζῆλος, τύπτω〉</p></section></article>\n<article id=\"entry-dgp-18224\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζηλόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 57 na letra ζ · nº geral 18224</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 arder por; procurar com ardor; desejar ardentemente algo, ac. 2 procurar imitar alguém, ac.: παῖς τὸ μὲν πρῶτον ζηλοῖ τὸν πατέρα plat. o filho imita em primeiro lugar o pai 3 desejar, aspirar a; aplicar-se a algo, ac. 3 ter como invejável; invejar; louvar; elogiar algo ou alguém, ac., por algo, ac., gen., ἐπί e dat., com part. ou or. conj. (ὅτι): ἠζήλουν τήνδε τὴν πόλιν xen. eu considerava invejável esta cidade, σὲ νῦν τοῦτο ζηλοῦν ἔχω; sóf. agora devo invejar-te por isso?, ζηλῶ σε τῆς εὐβουλίας ar. invejo a tua sabedoria, σὲ ζηλῶ θανόντα ésql. invejo-te por teres morrido 4 sentir inveja de, ac.: ζηλοῖ δέ τε γείτονα γείτων hes. o vizinho inveja o vizinho. 〈ζῆλος〉</p></section></article>\n<article id=\"entry-dgp-18225\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζήλωμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 58 na letra ζ · nº geral 18225</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 emulação; rivalidade 2 esforço para igualar-se a algo, gen. 3 objeto de emulação; alta posição; glória; felicidade. 〈ζηλόω〉</p></section></article>\n<article id=\"entry-dgp-18226\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζήλωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 59 na letra ζ · nº geral 18226</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 emulação; esforço para imitar 2 ciúme 3 inveja. 〈ζηλόω〉</p></section></article>\n<article id=\"entry-dgp-18227\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζηλωτέος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 60 na letra ζ · nº geral 18227</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de ζηλόω.</p></section></article>\n<article id=\"entry-dgp-18228\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζηλωτής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 61 na letra ζ · nº geral 18228</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 êmulo; imitador 2 que tem gosto por; admirador de algo, gen. 3 crist. prosélito zeloso; fanático 4 bíbl. ciumento. 〈ζηλόω〉</p></section></article>\n<article id=\"entry-dgp-18229\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζηλωτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 62 na letra ζ · nº geral 18229</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">capaz de zelo, de emulação, de entusiasmo por algo, περί e ac. 〈ζηλωτός〉</p></section></article>\n<article id=\"entry-dgp-18230\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζηλωτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 63 na letra ζ · nº geral 18230</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 invejado ou invejável (pessoa), por ou para alguém, dat., ὑπό e gen., quanto a algo, gen. 2 digno de inveja; invejado. 〈ζηλόω〉</p></section></article>\n<article id=\"entry-dgp-18231\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζημία,</h1><div class=\"entry-meta\"><span>DGP · ordem 64 na letra ζ · nº geral 18231</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. ζαμία, ας (ἡ) 1 prejuízo; dano; perda: ζημίαν ποιεῖν ou φέρειν ou ἐργάζεσθαί τινι causar prejuízo a alguém, ζημίαν λαβεῖν xen. sofrer um prejuízo, ζημίαν εἶναι νομίζειν ou ἡγεῖσθαι considerar como prejuízo 2 pena; castigo; punição: θάνατον ζημίαν ἐπιτίθεσθαι ou προθεῖναι ou ποιεῖν τινι fixar ou infligir a alguém a pena de morte 3 multa: ζημίαν ἐκτίνειν ou καταβάλλειν ou ἀποτίνειν pagar uma multa 4 causa de prejuízo; flagelo; peste: φανερὰν ζαμίαν ar. prejuízo evidente.</p></section></article>\n<article id=\"entry-dgp-18232\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζημιόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 65 na letra ζ · nº geral 18232</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ζημιώσω, aor. ἐζημίωσα) 1 fazer mal a; causar prejuízo a; lesar, ac.: οὐδὲν ζημιοῦν τὸ κοινόν isócr. não causar nenhum mal à comunidade, μηδὲν μηδένα ζημιοῦν plat. não causar nenhum prejuízo a ninguém 2 punir: τοὺς μὲν φύγῃ ἐζημίωσαν tuc. puniram alguns com o exílio 3 impor multa; multar: ζημιοῦν τινα μναῖς τρισί plat. impor a alguém multa de três minas. 〈ζημία〉</p></section></article>\n<article id=\"entry-dgp-18233\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζημιώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 66 na letra ζ · nº geral 18233</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">danoso; nocivo; prejudicial. 〈ζημία〉</p></section></article>\n<article id=\"entry-dgp-18234\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζημίωμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 67 na letra ζ · nº geral 18234</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 direito de punir 2 castigo; pena; multa. 〈ζημιόω〉</p></section></article>\n<article id=\"entry-dgp-18235\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζῆν</h1><div class=\"entry-meta\"><span>DGP · ordem 68 na letra ζ · nº geral 18235</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. pres. de ζάω.</p></section></article>\n<article id=\"entry-dgp-18236\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ζῆνα, Ζηνί, Ζηνός</h1><div class=\"entry-meta\"><span>DGP · ordem 69 na letra ζ · nº geral 18236</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. Ζεύς.</p></section></article>\n<article id=\"entry-dgp-18237\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ζήνων, ωνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 70 na letra ζ · nº geral 18237</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Zenão, filósofo da Escola de Eléia e do fundador do Estoicismo.</p></section></article>\n<article id=\"entry-dgp-18238\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζῆτα (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 71 na letra ζ · nº geral 18238</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">indecl. dzeta, letra do alfabeto grego.</p></section></article>\n<article id=\"entry-dgp-18239\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζητεῖ</h1><div class=\"entry-meta\"><span>DGP · ordem 72 na letra ζ · nº geral 18239</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. pres., ζήτει 3ª sing. impf. poét. ou imper. pres., de ζητέω.</p></section></article>\n<article id=\"entry-dgp-18240\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζητέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 73 na letra ζ · nº geral 18240</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐζήτουν, fut. ζητήσω, aor. ἐζήτεσα, perf. ἐζήτηκα) 1 procurar; buscar; esforçar-se por encontrar: ἐζήτουν τοὺς ἄρχοντας xen. procuravam os chefes 2 procurar obter; esforçar-se por alcançar: ζητεῖν πημάτων ἀπαλλαγάς ésql. buscar alcançar o fim dos tormentos, ζητεῖν τἀμήχανα eur. procurar o impossível 3 buscar para obter, inf.: ζητεῖς ἀναπείθειν ar. tu tentas persuadir 4 desejar; lamentar a falta de: ἵνα μὴ ζητέοιεν σιτία her. a fim de não buscarem comida, ζητεῖν Νέρωνα plut. sentir a falta de Nero ♦ at. e méd. 5 buscar conhecer; informar-se; investigar, ac., περί e gen. ou inter. indir.: τοὺς δράσαντας ἐζητοῦντο tuc. procuravam os autores, ζητεῖν τὸν φόνον plut. investigar o homicídio, ζητεῖν περὶ ἀδικημάτων din. inquirir sobre os crimes ♦ pas. τὸ ζητούμενον, τὰ ζητούμενα 6 objeto de discussão, de investigação, de exame.</p></section></article>\n<article id=\"entry-dgp-18241\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζήτημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 74 na letra ζ · nº geral 18241</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 objeto de pesquisa, de investigação 2 pesquisa; procura; busca 3 exame; indagação científica. 〈ζητέω〉</p></section></article>\n<article id=\"entry-dgp-18242\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζήτησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 75 na letra ζ · nº geral 18242</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 procura; busca: κατ᾽ Εὐρώπης ζήτησιν ἐκπλῶσαι her. embarcar em busca da Europa 2 exame; inspeção; revista, gen.: ζήτησιν ἐποιέετο τῶν νεῶν her. fazia a inspeção dos navios 3 pesquisa; investigação; estudo, a respeito de, περί e gen. ou ac.: ζήτησις περὶ τοῦ παντὸς φύσεως plat. pesquisa sobre a natureza do universo 4 interrogatório judicial. 〈ζητέω〉</p></section></article>\n<article id=\"entry-dgp-18243\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζητητέος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 76 na letra ζ · nº geral 18243</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de ζητέω.</p></section></article>\n<article id=\"entry-dgp-18244\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζητητής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 77 na letra ζ · nº geral 18244</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 aquele que busca; aquele que examina 2 inquisidor, em Atenas, magistrado incumbido da investigação de devedores e das somas devidas ao Estado. 〈ζητέω〉</p></section></article>\n<article id=\"entry-dgp-18245\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζητητικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 78 na letra ζ · nº geral 18245</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 disposto a buscar; capaz de buscar; apto para investigar, gen. ou περί e gen. 2 de caráter investigativo ♦ ἡ ζητητική [ἀγωγή] 3 a filosofia cética; ceticismo ♦ τὸ ζητητικόν 4 o que caracteriza a investigação. 〈ζητέω〉</p></section></article>\n<article id=\"entry-dgp-18246\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζητητός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 79 na letra ζ · nº geral 18246</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">investigado; procurado. 〈ζητέω〉</p></section></article>\n<article id=\"entry-dgp-18247\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζήω-ζῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 80 na letra ζ · nº geral 18247</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(pres. ζῶ, ζῇς, ζῇ, imper. ζῆ, opt. ζῴην, inf. ζῆν, impf. ἔζων, ἔζης, ἔζη, ἐζῶμεν, ἐζῆτε, ἔζων, fut. ζήσω e ζήσομαι, aor. ἔζησα, perf. ἔζηκα, m.-q.-perf. ἐζήκειν; o át. emprega, no aor., perf. e m.-q.-perf., formas de βιόω) 1 viver; estar vivo; ter vida: ζῆν ὀλίγα ἔτεα her. viver poucos anos, τὸ ζῆν κοινὸν εἶναι φαίνεται καὶ τοῖς φυτοῖς artt. parece que a vida é um atributo comum às plantas também 2 subsistir com; viver de, dat. ou ἐπί e dat., ἀπό ou ἐκ e gen., ou part.: ζῆν ἐργαζόμενος artt. viver de seu trabalho, ζῆν συκοφαντῶν and. viver de delações 3 viver; passar a vida de determinado modo (físico ou moral), ac., dat., adv.: εὖ ζῆν viver bem, ζῆν αἰσχρῶς viver em desonra, ζῆν βίον μοχθερόν sóf. levar uma vida penosa, ζῆν ἀβλαβεῖ βίῳ sóf. viver vida tranqüila 4 (não-animado) viver; ter vida; vigorar: ἄτη θύελλαι ζῶσι ésql. os turbilhões da desgraça estão vivos, ἀεὶ ζῇ ταῦτα sóf. essas [leis] estão em vigor, ὕδωρ ζῶν sept. água corrente 5 bíbl., rar., causat. no aor., fazer viver: ἐν τῇ ὁδῷ σου ζῆσόν με sept. faze-me viver em teu caminho.</p></section></article>\n<article id=\"entry-dgp-18248\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζιζάνιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 81 na letra ζ · nº geral 18248</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. joio; cizânia, erva daninha.</p></section></article>\n<article id=\"entry-dgp-18249\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζμάραγδος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 82 na letra ζ · nº geral 18249</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. = σμάραγδος.</p></section></article>\n<article id=\"entry-dgp-18250\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζμύρνα, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 83 na letra ζ · nº geral 18250</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl.= σμύρνα.</p></section></article>\n<article id=\"entry-dgp-18251\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζόη</h1><div class=\"entry-meta\"><span>DGP · ordem 84 na letra ζ · nº geral 18251</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ζωή.</p></section></article>\n<article id=\"entry-dgp-18252\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζορκάς, άδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 85 na letra ζ · nº geral 18252</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = δορκάς.</p></section></article>\n<article id=\"entry-dgp-18253\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζοφερός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 86 na letra ζ · nº geral 18253</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sombrio; escuro 2 lúgubre; sinistro. 〈ζόφος〉</p></section></article>\n<article id=\"entry-dgp-18254\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζοφόδορπις</h1><div class=\"entry-meta\"><span>DGP · ordem 87 na letra ζ · nº geral 18254</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só ac. pl. masc. ζοφοδόρπιδας) que se esconde para ter um magro jantar; que come no escuro, escondido. 〈ζόφος, δόρπον〉</p></section></article>\n<article id=\"entry-dgp-18255\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζόφος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 88 na letra ζ · nº geral 18255</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 obscuridade; trevas; escuridão 2 trevas subterrâneas; inferno 3 região da terra situada na escuridão; ocidente: πρὸς ζόφον ao ocidente 4 obscuridade (do estilo, da alma).</p></section></article>\n<article id=\"entry-dgp-18256\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζοφόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 89 na letra ζ · nº geral 18256</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 obscurecer-se; cobrir-se de trevas ♦ pas. 2 ἐζο­φωμένος part. perf.: tornado sombrio; tornado cego. 〈ζόφος〉</p></section></article>\n<article id=\"entry-dgp-18257\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζοφώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 90 na letra ζ · nº geral 18257</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 escuro; obscuro; turvo 2 opaco. 〈ζόφος〉</p></section></article>\n<article id=\"entry-dgp-18258\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζύγαστρον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 91 na letra ζ · nº geral 18258</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">caixinha; cofre de madeira. 〈ζυγόν〉</p></section></article>\n<article id=\"entry-dgp-18259\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζυγείς</h1><div class=\"entry-meta\"><span>DGP · ordem 92 na letra ζ · nº geral 18259</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor.2 pas. de ζεύγνυμι.</p></section></article>\n<article id=\"entry-dgp-18260\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζύγιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 93 na letra ζ · nº geral 18260</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 apropriado para o jugo; que é posto sob jugo: ζύγιοι ἵπποι sóf. cavalos que, colocados sob jugo, servem numa quadriga como animais de tiro, enquanto os dois outros que os ladeiam (σειραῖοι) são governados pelas rédeas 2 com κῶπαι, remos do banco do meio do navio 3 que conjunge; que preside as uniões, epít. de certas divindades femininas. 〈ζυγόν〉</p></section></article>\n<article id=\"entry-dgp-18261\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζυγίτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 94 na letra ζ · nº geral 18261</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ζευγίτης.</p></section></article>\n<article id=\"entry-dgp-18262\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζυγόδεσμον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 95 na letra ζ · nº geral 18262</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">correia que prende o jugo ao timão. 〈ζυγόν, δεσμός〉</p></section></article>\n<article id=\"entry-dgp-18263\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζυγομαχέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 96 na letra ζ · nº geral 18263</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 lutar com um companheiro 2 combater com os companheiros; lutar contra alguém, πρός e ac., por algo, περί ou ὑπέρ e gen. 〈ζυγόν, μάχομαι〉</p></section></article>\n<article id=\"entry-dgp-18264\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζυγόν, οῦ (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 97 na letra ζ · nº geral 18264</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 o que serve para juntar dois objetos; jugo; canga: ἐπὶ ζυγὸν αὐχένι θεῖναι βουσί hes. colocar o jugo na nuca dos bois; colocar os bois sob o jugo 2 em Roma, jugo, peça de madeira sob a qual se faziam passar os prisioneiros de guerra 3 jugo; opressão: δουλείας ζ. sóf. jugo da servidão, ἀνάγκης ζ. eur. jugo da necessidade 4 Náut., em ger. no pl. viga transversal que une os dois lados do navio; vau 5 Náut. banco de remeiro que se estende de um lado ao outro do navio, partic. o banco do meio: ὑπὸ ζυγά hom. sob os bancos 6 junção 7 barra da cítara 8 correia da sandália 9 braço da balança; balança: ζυγῷ ou ἐν τῷ ζυγῷ ἱστάναι pôr na balança 10 Astron. Balança, constelação 11 casal; par: κατὰ ζυγά artt. aos pares 12 fila de soldados; linha; fileira: ἐν τῷ πρώτῳ ζυγῷ tuc. na primeira linha, κατὰ ζυγόν pol. linha por linha.</p></section></article>\n<article id=\"entry-dgp-18265\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζυγός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 98 na letra ζ · nº geral 18265</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ζυγόν.</p></section></article>\n<article id=\"entry-dgp-18266\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζυγόσταθμος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 99 na letra ζ · nº geral 18266</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">balança. 〈ζυγόν, σταθμός〉</p></section></article>\n<article id=\"entry-dgp-18267\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζυγοστατέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 100 na letra ζ · nº geral 18267</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pôr na balança; pesar ♦ méd. pas. 2 estar na balança; estar em equilíbrio; equilibrar-se. 〈ζυγόν, ἵστημι〉</p></section></article>\n<article id=\"entry-dgp-18268\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζυγόφι(ν)</h1><div class=\"entry-meta\"><span>DGP · ordem 101 na letra ζ · nº geral 18268</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. sing. ép. de ζυγόν.</p></section></article>\n<article id=\"entry-dgp-18269\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζυγοφόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 102 na letra ζ · nº geral 18269</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que leva o jugo. 〈ζυγόν, φέρω〉</p></section></article>\n<article id=\"entry-dgp-18270\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζυγόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 103 na letra ζ · nº geral 18270</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 colocar sob jugo; ligar 2 subjugar 3 pesar na balança 4 fixar a barra transversal em uma cítara. 〈ζυγόν〉</p></section></article>\n<article id=\"entry-dgp-18271\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζυγωτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 104 na letra ζ · nº geral 18271</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">atrelado. 〈ζυγόν〉</p></section></article>\n<article id=\"entry-dgp-18272\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζύμη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 105 na letra ζ · nº geral 18272</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fermento; levedura. 〈ζέω〉</p></section></article>\n<article id=\"entry-dgp-18273\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζυμίτης ἄρτος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 106 na letra ζ · nº geral 18273</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pão feito de massa fermentada. 〈ζύμη〉</p></section></article>\n<article id=\"entry-dgp-18274\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζυμόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 107 na letra ζ · nº geral 18274</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fazer fermentar 2 pôr em efervescência ♦ méd. pas. 3 fermentar; levedar. 〈ζύμη〉</p></section></article>\n<article id=\"entry-dgp-18275\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζύμωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 108 na letra ζ · nº geral 18275</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fermentação. 〈ζυμόω〉</p></section></article>\n<article id=\"entry-dgp-18276\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 109 na letra ζ · nº geral 18276</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">contr. de ζάω.</p></section></article>\n<article id=\"entry-dgp-18277\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζωαγρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 110 na letra ζ · nº geral 18277</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ζωγρεῖον.</p></section></article>\n<article id=\"entry-dgp-18278\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζωάγριος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 111 na letra ζ · nº geral 18278</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pago por ter salvo a vida ♦ τὸ ζωάγριον, τὰ ζωάγρια 2 resgate da vida; resgate: ζ. τίνειν pagar resgate, ζ. ὀφέλλειν ser devedor de resgate, ζ. ἀποθύειν oferecer em sacrifício para obter a vida ou por ter conseguido salvá-la. 〈ζωός, ἀγρεύω〉</p></section></article>\n<article id=\"entry-dgp-18279\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζωγραφεῖον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 112 na letra ζ · nº geral 18279</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ateliê de pintor. 〈ζωγράφος〉</p></section></article>\n<article id=\"entry-dgp-18280\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζωγραφέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 113 na letra ζ · nº geral 18280</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pintar 2 ornar com pinturas. 〈ζωγράφος〉</p></section></article>\n<article id=\"entry-dgp-18281\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζωγραφία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 114 na letra ζ · nº geral 18281</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pintura; arte de pintar 2 pintura; quadro. 〈ζωγράφος〉</p></section></article>\n<article id=\"entry-dgp-18282\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζωγράφος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 115 na letra ζ · nº geral 18282</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pintor. 〈ζωός, γράφω〉</p></section></article>\n<article id=\"entry-dgp-18283\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζωγρεῖον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 116 na letra ζ · nº geral 18283</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 viveiro 2 jaula 3 zoológico. 〈ζωγρεύς〉</p></section></article>\n<article id=\"entry-dgp-18284\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζωγρεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 117 na letra ζ · nº geral 18284</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pescador. 〈ζωγρέω〉</p></section></article>\n<article id=\"entry-dgp-18285\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζωγρέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 118 na letra ζ · nº geral 18285</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 prender vivo; aprisionar; capturar 2 prender; pôr na cadeia 3 reanimar. 〈ζωός, ἀγρέω〉</p></section></article>\n<article id=\"entry-dgp-18286\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζωγρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 119 na letra ζ · nº geral 18286</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">captura de um prisioneiro vivo: ζωγρίῃ λαβεῖν ou αἱρέειν τινά her. prender alguém vivo.</p></section></article>\n<article id=\"entry-dgp-18287\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζώγριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 120 na letra ζ · nº geral 18287</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ζωγρεῖον.</p></section></article>\n<article id=\"entry-dgp-18288\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζῳδιακός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 121 na letra ζ · nº geral 18288</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que diz respeito a figuras de animais: ζῳδ. κύκλος plut. o zodíaco. 〈ζῴδιον〉</p></section></article>\n<article id=\"entry-dgp-18289\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζῴδιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 122 na letra ζ · nº geral 18289</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pequena representação de animal ou de humano, desenhada ou esculpida; imagem; estatueta 2 pl. signos do zodíaco.</p></section></article>\n<article id=\"entry-dgp-18290\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζωέμεν</h1><div class=\"entry-meta\"><span>DGP · ordem 123 na letra ζ · nº geral 18290</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ζωέμεναι inf. pres. ép., ζώεσκον impf. iter., de ζώω.</p></section></article>\n";
